# 361 tarfile 的 TarFile 内存读写面：fileobj=BytesIO 建归档/w 模式、
# addfile（文件/目录/符号链接）、close 尾块与 RECORDSIZE 补齐、r 模式
# getmembers/getnames/getmember/extractfile、迭代/with/contains、KeyError。
# 对拍 CPython 3.14：归档字节与全部输出逐字节一致。
# pyadamas: lang-gaps
import base64
import tarfile
from io import BytesIO
from tarfile import TarInfo


buf = BytesIO()
tf = tarfile.open(fileobj=buf, mode="w")

a = TarInfo("a.txt")
a.size = 5
a.mtime = 1700000000
a.mode = 0o644
tf.addfile(a, BytesIO(b"hello"))

b = TarInfo("dir/b.bin")
b.size = 4
b.mtime = 1700000001
tf.addfile(b, BytesIO(b"\x00\x01\x02\xff"))

empty = TarInfo("empty.txt")
empty.mtime = 1700000002
tf.addfile(empty)

d = TarInfo("dir")
d.type = tarfile.DIRTYPE
d.mode = 0o755
d.mtime = 1699999999
tf.addfile(d)

s = TarInfo("ln")
s.type = tarfile.SYMTYPE
s.linkname = "a.txt"
s.mtime = 1700000000
tf.addfile(s)

tf.close()
print(len(buf.getvalue()))
print(base64.b64encode(buf.getvalue()).decode())

buf.seek(0)
rd = tarfile.open(fileobj=buf, mode="r")
print(rd.getnames())
for m in rd:
    print(m.name, m.type, m.size, m.mtime, m.mode, m.uid, m.gid, m.linkname)
    print(" ", m.isfile(), m.isdir(), m.issym(), m.islnk(), m.isdev())

print(rd.getmember("a.txt").size)
print(rd.getmember("dir").name, rd.getmember("dir/").name)
print(rd.extractfile("a.txt").read())
print(base64.b64encode(rd.extractfile("dir/b.bin").read()).decode())
print(rd.extractfile("empty.txt").read())
print(rd.extractfile("ln").read())
try:
    rd.getmember("nope")
except KeyError as e:
    print(type(e).__name__)
rd.close()
try:
    rd.getmembers()
except OSError as e:
    print(type(e).__name__, str(e))

# ── with + 磁盘路径（重新打开同一份字节）─────────────────────────
import os.path as _osp
import tempfile
d2 = tempfile.mkdtemp()
p = d2 + "/t.tar"
with tarfile.open(p, "w") as tf2:
    x = TarInfo("x.txt")
    x.size = 3
    x.mtime = 1700000000
    tf2.addfile(x, BytesIO(b"xyz"))
with tarfile.open(p) as tf3:
    print(tf3.getnames())
    print(tf3.extractfile("x.txt").read())
q = d2 + "/not.tar"
f = open(q, "w")
f.write("hello")
f.close()
print(tarfile.is_tarfile(p), tarfile.is_tarfile(q))
print(_osp.getsize(p) == len(buf.getvalue()))

# ── ignore_zeros：中间塞一个空零块时跳过继续读 ──────────────────
b0 = BytesIO()
tz = tarfile.open(fileobj=b0, mode="w")
z1 = TarInfo("z1.txt")
z1.size = 2
z1.mtime = 1700000000
tz.addfile(z1, BytesIO(b"aa"))
z2 = TarInfo("z2.txt")
z2.size = 2
z2.mtime = 1700000000
tz.addfile(z2, BytesIO(b"bb"))
tz.close()
pz: bytes = b0.getvalue()
pg: bytes = pz[0:1024] + b"\x00" * 512 + pz[1024:]
with tarfile.open(fileobj=BytesIO(pg)) as rz1:
    print(rz1.getnames())
with tarfile.open(fileobj=BytesIO(pg), ignore_zeros=True) as rz2:
    print(rz2.getnames())
    print(rz2.extractfile("z2.txt").read())
